const std = @import("std");
const sharp = [_][]const u8{ "C", "C#", "D", "D#", "E", "F", "F#", "G", "G#", "A", "A#", "B" };
const flat = [_][]const u8{ "C", "Db", "D", "Eb", "E", "F", "Gb", "G", "Ab", "A", "Bb", "B" };
pub const Scale = struct {
    notes: [12][]const u8,
    start: usize,
    pub fn init(tonic: []const u8) !Scale {
        var flats = false;
        for ([_][]const u8{ "F", "Bb", "Eb", "Ab", "Db", "Gb", "d", "g", "c", "f", "bb", "eb" }) |s| {
            if (std.mem.eql(u8, s, tonic)) flats = true;
        }
        const notes = if (flats) flat else sharp;
        var normalized: [2]u8 = undefined;
        if (tonic.len == 0 or tonic.len > 2) return error.InvalidTonic;
        @memcpy(normalized[0..tonic.len], tonic);
        normalized[0] = std.ascii.toUpper(normalized[0]);
        for (notes, 0..) |s, i| {
            if (std.mem.eql(u8, s, normalized[0..tonic.len])) return .{ .notes = notes, .start = i };
        }
        return error.InvalidTonic;
    }
    pub fn chromatic(s: Scale) [12][]const u8 {
        var out: [12][]const u8 = undefined;
        for (&out, 0..) |*n, i| n.* = s.notes[(s.start + i) % 12];
        return out;
    }
    pub fn interval(s: Scale, a: std.mem.Allocator, steps: []const u8) ![][]const u8 {
        const out = try a.alloc([]const u8, steps.len + 1);
        errdefer a.free(out);
        var index = s.start;
        out[0] = s.notes[index];
        for (steps, 0..) |c, i| {
            index = (index + switch (c) {
                'm' => @as(usize, 1),
                'M' => 2,
                'A' => 3,
                else => return error.InvalidInterval,
            }) % 12;
            out[i + 1] = s.notes[index];
        }
        return out;
    }
};

