// Test scenarios adapted from the MIT-licensed Exercism Python track and
// exercism/problem-specifications (4289d4ec9ed947cd785939ab82c479bb8d4f2cc7).
const std = @import("std");
const t = std.testing;
const m = @import("scale_generator.zig");
test "chromatic sharp flat and interval modes" {
    const c = try m.Scale.init("C");
    try t.expectEqualStrings("C#", c.chromatic()[1]);
    const f = try m.Scale.init("F");
    try t.expectEqualStrings("Gb", f.chromatic()[1]);
    const a = try c.interval(t.allocator, "MMmMMMm");
    defer t.allocator.free(a);
    const expected = [_][]const u8{ "C", "D", "E", "F", "G", "A", "B", "C" };
    for (a, expected) |x, y| try t.expectEqualStrings(x, y);
    const b = try (try m.Scale.init("bb")).interval(t.allocator, "MmMMmMM");
    defer t.allocator.free(b);
    try t.expectEqualStrings("Db", b[2]);
    const h = try (try m.Scale.init("a")).interval(t.allocator, "MmMMmAm");
    defer t.allocator.free(h);
    try t.expectEqualStrings("G#", h[6]);
    try t.expectError(error.InvalidTonic, m.Scale.init("H"));
    try t.expectError(error.InvalidInterval, c.interval(t.allocator, "X"));
}
test "python test_chromatic_scale_with_sharps" {
    const scale = try m.Scale.init("C");
    const out = scale.chromatic();
    const expected = [_][]const u8{ "C", "C#", "D", "D#", "E", "F", "F#", "G", "G#", "A", "A#", "B" };
    try t.expectEqual(expected.len, out.len);
    for (out, expected) |x, y| try t.expectEqualStrings(y, x);
}
